var i=`0170-risotto-alla-milanese`;var a=`world-0170`;var n=`IT`;var o=`southern-europe`;var r=4;var s=31;var l={en:`Risotto alla Milanese`,ua:`Ризото по-міланськи`};var g={en:`A classic dish from Italy, featuring yellow onion, arborio rice, parmigiano reggiano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: жовта цибуля, рис арборіо, парміджано реджано. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 6 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 6 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:6,i:[[`yellow-onion`,100,`g`],[`unsalted-butter`,45,`g`]]},{en:`Coat the rice in the warm fat with the aromatics and toast gently for about 3 minutes without browning.`,ua:`Змішайте рис із теплим жиром та ароматичними складниками й прогрівайте приблизно 3 хвилин, не підрум’янюючи.`,t:[`sauteing`,`risotto-method`],m:3,i:[[`arborio-rice`,320,`g`]]},{en:`Add hot stock gradually, one ladle at a time, stirring regularly for about 19 minutes until the rice is creamy yet firm in the center.`,ua:`Поступово вливайте гарячий бульйон по одному ополонику, регулярно помішуючи приблизно 19 хвилин, поки рис стане кремовим, але залишиться з легкою пружністю всередині.`,t:[`risotto-method`],m:19,i:[[`beef-stock`,1050,`ml`],[`dry-white-wine`,100,`ml`],[`saffron-threads`,.3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parmigiano-reggiano`,85,`g`],[`unsalted-butter`,35,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:i,id:a,country:`IT`,region:o,servings:4,minutes:31,title:l,text:g,steps:u};export{n as country,d as default,a as id,s as minutes,o as region,r as servings,i as slug,u as steps,g as text,l as title};